  "Aucun##thème": "None",
  "L'appli change d'allure d'elle-même : fond, couleur, boutons, titres, motif et petit décor sur l'accueil. Les fêtes sont plus marquées ; les saisons habillent le reste de l'année. Les couleurs des graphiques ne changent jamais.": "The app changes its look by itself: background, colour, buttons, titles, pattern and a little decoration on the home screen. Celebrations are more striking; seasons dress up the rest of the year. Chart colours never change.",
