  "Mémoire de l'assistant ({n})": "Assistant's memory ({n})",
  "Oublier ce fait": "Forget this fact",
  "Rien pour l'instant. Dis par exemple à l'assistant « souviens-toi que… » ; il retient aussi de lui-même ce que tu lui expliques (contexte, prélèvements, préférences).": "Nothing yet. For example, tell the assistant “remember that…”; it also remembers of its own accord what you explain to it (context, direct debits, preferences).",
  "Ces faits sont propres à chaque membre et joints aux consignes de l'assistant à chaque conversation.": "These facts are specific to each member and added to the assistant's instructions in every conversation.",
  "Garde sur cet appareil les dernières données de synthèse (soldes, mois, patrimoine, budget, opérations récentes) 7 jours au plus : l'appli s'ouvre tout de suite, même sans réseau. Effacées à la déconnexion ; jamais les factures, documents ni conversations.": "Keeps the latest summary data (balances, month, wealth, budget, recent transactions) on this device for up to 7 days: the app opens straight away, even with no network. Erased when you sign out; never invoices, documents or conversations.",
  "Données effacées de cet appareil": "Data erased from this device",
  "Actif au prochain lancement de l'appli": "Active the next time the app starts",
  "Un nouveau lien remplace l'ancien : les agendas abonnés à l'ancien ne se mettront plus à jour. Continuer ?": "A new link replaces the old one: calendars subscribed to the old one will stop updating. Continue?",
  "Couper l'abonnement ? Les agendas abonnés ne recevront plus l'échéancier.": "Turn off the subscription? Subscribed calendars will no longer receive the schedule.",
  "Échéancier dans Calendrier": "Schedule in Calendar",
  "Abonne Calendrier (iPhone, Mac) à ton échéancier : tâches, mensualités, fins de crédit, garanties, documents qui expirent, calendrier fiscal, avec un rappel la veille. Mis à jour toutes les 6 heures ; le lien est privé, garde-le pour toi.": "Subscribe Calendar (iPhone, Mac) to your schedule: tasks, monthly payments, loan end dates, warranties, expiring documents, tax calendar, with a reminder the day before. Updated every 6 hours; the link is private, keep it to yourself.",
  "Copie ce lien maintenant : il ne sera plus affiché.": "Copy this link now: it won't be shown again.",
  "S'abonner sur cet appareil": "Subscribe on this device",
  "Copier le lien": "Copy link",
  "Abonnement actif depuis le {date}": "Subscription active since {date}",
  "lu {quand}": "read {quand}",
  "Nouveau lien": "New link",
  "Couper##abonnement": "Turn off",
  "Créer le lien d'abonnement": "Create the subscription link",
  "{quoi} : indisponible en mode démo (rien ne doit toucher à tes vrais appareils ni à tes vrais accès).": "{quoi}: unavailable in demo mode (nothing must touch your real devices or your real access).",
  "Mode démo actif": "Demo mode on",
  "Données fictives. Touche pour en sortir.": "Fictional data. Tap to leave.",
  "Le mode démo est actif.": "Demo mode is on.",
  "Tout ce que tu vois est fictif : la famille, les comptes, les opérations, les factures, le patrimoine. Tes vraies données restent cachées.": "Everything you see is fictional: the family, the accounts, the transactions, the invoices, the wealth. Your real data stays hidden.",
  "Sortie impossible": "Couldn't leave demo mode",
  "Vérification…": "Verifying…",
  "Quitter le mode démo": "Leave demo mode",
  "Face ID, Touch ID ou le code de l'appareil est demandé : personne ne peut sortir de la démo à ta place.": "Face ID, Touch ID or the device passcode is required: nobody can leave the demo in your place.",
  "Montre Pécule sans rien dévoiler : l'appli passe sur une famille imaginaire, avec ses comptes, ses opérations, ses factures, son patrimoine et son échéancier. Tout fonctionne, l'assistant compris, mais sur ces données fictives.": "Show Pécule without revealing anything: the app switches to an imaginary family, with its accounts, transactions, invoices, wealth and schedule. Everything works, the assistant included, but on this fictional data.",
  "Sur cet appareil seulement : les autres membres et tes autres appareils restent sur les vraies données.": "On this device only: other members and your other devices stay on the real data.",
  "Pour revenir à tes données : Face ID ou Touch ID.": "To get back to your data: Face ID or Touch ID.",
  "Synchronisation, notifications et clés d'accès sont coupées pendant la démo ; les données fictives sont remises à neuf chaque jour.": "Sync, notifications and passkeys are switched off during the demo; the fictional data is reset every day.",
  "Mode démo indisponible": "Demo mode unavailable",
  "Préparation de la démo…": "Preparing the demo…",
  "Passer en mode démo": "Switch to demo mode",
  "Mode démo non configuré": "Demo mode not set up",
  "Réglage indisponible": "Setting unavailable",
  "Réglage commun à toute la famille. Le fournisseur choisi reçoit tout ce que Pécule confie à l'IA : questions à l'assistant, factures, documents et bulletins de paie. Les clés sont chiffrées et ne sont plus jamais affichées. Un fournisseur est essayé avant d'être choisi ou modifié : si l'essai échoue, rien ne change.": "A setting shared by the whole family. The chosen provider receives everything Pécule entrusts to AI: questions to the assistant, invoices, documents and payslips. Keys are encrypted and never shown again. A provider is tested before being chosen or changed: if the test fails, nothing changes.",
  "Le mode vocal passe toujours par la ressource Microsoft Foundry.": "Voice mode always goes through the Microsoft Foundry resource.",
  "Le mode vocal a besoin d'une ressource Microsoft Foundry (son nom et sa clé).": "Voice mode needs a Microsoft Foundry resource (its name and its key).",
