  "Pour recevoir les notifications sur l'iPhone, installe d'abord Pécule sur l'écran d'accueil (Partager → Sur l'écran d'accueil), puis ouvre l'appli depuis son icône et reviens ici.": "To receive notifications on the iPhone, first install Pécule on the Home Screen (Share → Add to Home Screen), then open the app from its icon and come back here.",
  "Ce navigateur ne gère pas les notifications.": "This browser doesn't support notifications.",
  "Reçois sur cet appareil les alertes utiles : opérations à classer, prélèvement nouveau ou inhabituel, solde bas, loyer non reçu, échéances, garanties, enveloppes, et le résumé de la semaine.": "Get the useful alerts on this device: transactions to categorise, new or unusual direct debit, low balance, rent not received, due dates, warranties, envelopes, and the weekly summary.",
  "Activer sur cet appareil": "Turn on for this device",
  "Notification d'essai envoyée": "Test notification sent",
  "Aucun appareil n'a reçu l'essai": "No device received the test",
  "Essai": "Test",
  "Désactiver sur cet appareil": "Turn off for this device",
  "Dernières notifications": "Latest notifications",
  "Import impossible": "Couldn't import",
  "Sur BoursoBank : {lien}, tous les comptes, format CSV. Tu peux redéposer le même fichier : rien n'est compté deux fois, et un nom déjà posé n'est jamais remplacé.": "On BoursoBank: {lien}, all accounts, CSV format. You can upload the same file again: nothing is counted twice, and a name already set is never replaced.",
  "Pour un prélèvement ou un virement, la synchronisation ne transmet souvent qu'une référence. L'export de BoursoBank porte le nom du créancier : dépose-le ici pour nommer ces opérations et les classer comme celles du même nom.": "For a direct debit or a transfer, the sync often passes on only a reference. BoursoBank's export carries the creditor's name: upload it here to name these transactions and categorise them like those with the same name.",
  "Import en cours…": "Importing…",
  "Déposer l'export CSV": "Upload the CSV export",
  "Équivalences amusantes": "Fun equivalents",
  "Pendant un thème, les dépenses se lisent aussi dans l'unité du moment (litres de bière à la Saint-Patrick, kilos de bonbons à Halloween…) et, toute l'année, en temps de travail d'après tes bulletins de paie. Avec, sur l'accueil, « Le chiffre du moment » et ce que coûte la fête en cours. Aucun montant ne change. Valable sur tous tes appareils, assistant compris.": "During a theme, spending can also be read in the unit of the moment (litres of beer on St Patrick's Day, kilos of sweets at Halloween…) and, all year round, in working time based on your payslips. Plus, on the home screen, “Figure of the moment” and what the current celebration is costing. No amount changes. Applies on all your devices, the assistant included.",
  "En ce moment ({theme}) : {unite}, soit 100 € ≈ {equivalent}.": "Right now ({theme}): {unite}, so €100 ≈ {equivalent}.",
  "En ce moment ({theme}) : {unite}.": "Right now ({theme}): {unite}.",
  "Équivalences activées": "Equivalents turned on",
  "Équivalences désactivées": "Equivalents turned off",
  "Logo": "Logo",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment (en ce moment : {theme}).": "The everyday chest, on the background of your choice. In the app and in the browser tab, it takes on the decoration of the current theme by itself (right now: {theme}).",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment.": "The everyday chest, on the background of your choice. In the app and in the browser tab, it takes on the decoration of the current theme by itself.",
  "Icône sur l'écran d'accueil": "Home Screen icon",
  "Comme le logo": "Same as the logo",
  "L'iPhone garde l'icône du jour où Pécule a été ajouté à l'écran d'accueil : elle ne peut pas changer toute seule. Pour en changer, ouvre Pécule dans Safari, choisis l'icône ici, supprime l'ancienne de l'écran d'accueil, puis Partager → « Sur l'écran d'accueil ». Il faudra te reconnecter et réactiver les notifications.": "The iPhone keeps the icon from the day Pécule was added to the Home Screen: it can't change by itself. To change it, open Pécule in Safari, choose the icon here, delete the old one from the Home Screen, then Share → “Add to Home Screen”. You'll need to sign in again and turn notifications back on.",
  "Tu es dans l'appli installée : fais ce choix depuis Safari, c'est lui qui crée l'icône.": "You're in the installed app: make this choice from Safari, as Safari is what creates the icon.",
