  "Le jour J, Pécule prend les couleurs de l'anniversaire sur tous les appareils de la famille et le souhaite sur l'accueil. La liste est partagée par le foyer ; l'année est facultative.": "On the day, Pécule dresses up for the birthday on all the family's devices and wishes it on the home screen. The list is shared by the household; the year is optional.",
