  "{n} seulement dans Pécule": "{n} only in Pécule",
  "« Datées autrement » : des achats de fin de mois que la banque prélève un mois plus tard que ce que Pécule supposait. La date de la banque fera foi.": "“Dated differently”: end-of-month purchases that the bank debits a month later than Pécule assumed. The bank's date will prevail.",
  "Comparer avec mes comptes actuels": "Compare with my current accounts",
  "Accord bancaire à renouveler · {banque}": "Bank consent to renew · {banque}",
  "Ta clé personnelle": "Your personal key",
  "Oublier ma clé": "Forget my key",
  "Oublier ta clé personnelle et tes accords ? Les opérations déjà lues restent dans Pécule.": "Forget your personal key and your consents? Transactions already read stay in Pécule.",
  "J'ai des comptes à mon seul nom": "I have accounts in my name only",
  "L'usage gratuit d'Enable Banking ne couvre que les comptes de la personne inscrite. Si tu as des comptes à ton seul nom, crée ta propre application sur enablebanking.com et donne ici sa clé : elle servira à tes accords.": "Free use of Enable Banking only covers the accounts of the person who signed up. If you have accounts in your name only, create your own application on enablebanking.com and enter its key here: it will be used for your consents.",
  "Synchronisations bancaires": "Bank syncs",
  "alertes techniques journal audit synchronisation banque": "technical alerts log audit sync bank",
  "Synchroniser les comptes bancaires": "Sync bank accounts",
  "Compte importé": "Imported account",
  "Dépose l'export de ta banque (OFX, QIF ou CSV) : ses opérations rejoignent le compte choisi. Tu peux redéposer un fichier qui recouvre le précédent, rien n'est ajouté deux fois.": "Drop your bank's export (OFX, QIF or CSV): its transactions join the chosen account. You can drop a file that overlaps the previous one; nothing is added twice.",
