  "Bienvenue dans Pécule": "Welcome to Pécule",
  "Cette installation est neuve. Crée le premier membre du foyer : il en sera l'administrateur.": "This is a new installation. Create the household's first member: they will be its administrator.",
  "Ton prénom": "Your first name",
  "Code d'installation": "Installation code",
