  "Par l'interface officielle de ta banque, en lecture seule (Enable Banking, gratuit pour un usage personnel).": "Through your bank's official interface, read-only (Enable Banking, free for personal use).",
  "Importer un fichier de ta banque": "Import a file from your bank",
  "L'export OFX, QIF ou CSV de ton espace client : aucun service à relier.": "The OFX, QIF or CSV export from your online banking: no service to connect.",
  "Brancher l'assistant": "Set up the assistant",
  "Facultatif : avec ta propre clé d'IA, Pécule lit tes factures et répond à tes questions.": "Optional: with your own AI key, Pécule reads your invoices and answers your questions.",
  "Bien démarrer": "Getting started",
  "Pécule est installé et ton foyer est créé. Donne-lui ses premières opérations : tout le reste en découle.": "Pécule is installed and your household is created. Give it its first transactions: everything else follows from them.",
  "Voir Pécule rempli, avec une famille fictive": "See Pécule filled in, with a fictional family",
  "Écrans affichés": "Screens shown",
  "Un écran retiré sort du menu, de la recherche et des raccourcis pour tout le foyer. Ses données restent en place : le remettre les retrouve telles quelles.": "A removed screen leaves the menu, search and shortcuts for the whole household. Its data stays in place: bring it back and you find everything as it was.",
  "Seul l'administrateur du foyer peut changer ces réglages.": "Only the household administrator can change these settings.",
  "Personnes et banques": "People and banks",
  "Personnes sans connexion": "People without a login",
  "Un enfant, par exemple : ses comptes portent son prénom et lui sont attribués. Sépare les prénoms par une virgule.": "A child, for example: accounts bearing their first name are assigned to them. Separate first names with a comma.",
  "Banques des comptes professionnels": "Banks holding business accounts",
  "Nom de la banque": "Bank name",
  "Les comptes de ces banques sont rangés à part, masqués et hors statistiques dès leur arrivée.": "Accounts from these banks are kept apart, hidden and excluded from statistics as soon as they arrive.",
  "Foyer enregistré": "Household saved",
  "Biens, valeur, loyers, taxe foncière": "Properties, value, rents, property tax",
  "Positions, cours, journal des mouvements": "Holdings, prices, movement log",
  "Scénarios de patrimoine à plusieurs années": "Wealth scenarios over several years",
  "Bulletins de paie, sources de revenus": "Payslips, income sources",
  "Impôt sur le revenu, taxes foncières": "Income tax, property taxes",
  "Carrière, trimestres, estimations": "Career, quarters, estimates",
  "L'assistant n'est pas branché": "The assistant isn't set up",
  "Pécule fonctionne sans IA : seules la lecture automatique des factures et des documents et les réponses à tes questions en dépendent. Pour les activer, ajoute la clé de ton fournisseur d'IA.": "Pécule works without AI: only the automatic reading of invoices and documents and the answers to your questions depend on it. To turn them on, add your AI provider's key.",
  "Réglages → Assistant": "Settings → Assistant",
  "Opération ajoutée": "Transaction added",
  "Ajouter une opération": "Add a transaction",
  "Dépense": "Expense",
  "Revenu": "Income",
  "Boulangerie, loyer, salaire…": "Bakery, rent, salary…",
  "L'opération est classée comme les autres (règles, libellés déjà classés) ; tu peux ensuite changer sa catégorie. Si le compte a un solde, il suit.": "The transaction is categorised like the others (rules, labels already categorised); you can change its category afterwards. If the account has a balance, it follows.",
