  "désactivées": "turned off",
  "Réglage du foyer : tous les chiffres datés changent de jour.": "Household setting: every dated figure changes its day.",
  "Écrans retirés du menu": "Screens removed from the menu",
  "Aucune donnée n'est supprimée.": "No data is deleted.",
  "Modifier les réglages": "Change the settings",
  "Masqué : retiré de ton accueil ; ses opérations restent comptées.": "Hidden: removed from your home screen; its transactions are still counted.",
  "Affiché de nouveau sur ton accueil.": "Shown on your home screen again.",
